Identify the restaurant's culinary type and generate a customized B2B email pitching the exact matching shallot grade and offering a 1kg sample box.

parameters.jsCode:
const leadItem = $('3. Loop Leads Sequentially').item.json;
const aiContent = $input.first().json.message?.content || $input.first().json;

let parsed;
try {
  parsed = typeof aiContent === 'string' ? JSON.parse(aiContent) : aiContent;
} catch (e) {
  parsed = {
    selected_subject: `Authentic Boyolali Fried Shallots Supply for ${leadItem.clean_name}`,
    body_html: `<p>Hi ${leadItem.clean_name} team,</p><p>We supply authentic Boyolali fried shallots (Grade S Murni 100% & Grade A Crispy), Halal certified (ID33110018517710724). Can we send a complimentary 1kg sample pack to your kitchen at ${leadItem.address}?</p><p>Best regards,<br>Fahru Hernan<br>Juragan by Anak Bawang (+62 821-3373-1213)</p>`,
    body_text: `Hi ${leadItem.clean_name} team, we supply authentic Boyolali fried shallots. May we send a free 1kg sample to your kitchen at ${leadItem.address}?`
  };
}

return [{
  json: {
    lead_id: leadItem.lead_id,
    recipient_email: leadItem.email,
    restaurant_name: leadItem.clean_name,
    subject: parsed.selected_subject || `Shallot Supply for ${leadItem.clean_name}`,
    body_html: parsed.body_html,
    body_text: parsed.body_text
  }
}];
